public Object[] tokenizerV3(String value, String[] delimeters) {
    List<String> list = new Vector<>();
    for (String delimeter : delimeters) {
        list.addAll(Arrays.asList(value.split("\\" + delimeter)));
        list.add(delimeter);
    }
    return list.toArray();
}

