public int solution(int X, int[] A) {
    int sum1 = IntStream.range(0, X + 1).sum();
    int sum2 = Arrays.stream(A).distinct().sum();
    for (int i = 0; i < A.length; i++) {
        if (sum1 == sum2) return i;
        else if (A[i] <= X) {
            sum2 -= A[i];
        }
    }
    return -1;
}

