            out.write(buffer, 0, read);
        }
        success = true;
    } catch (java.io.IOException exc) {
        logger.error(Logger.SECURITY_FAILURE, "Problem decoding file to file", exc);
    } finally {
        try {
            in.close();
        } catch (Exception exc) {
        }
        try {
            out.close();
        } catch (Exception exc) {
        }
    }
    return success;
}

