public boolean deleteDirectory(File path) {
    if (path.exists()) {
        File[] files = path.listFiles();
        if (null != files) {
            Arrays.stream(files).forEach(file -> {
                if (file.isDirectory()) {
                    deleteDirectory(file);
                } else {
                    file.delete();
                }
            });
        }
    }
    return (path.delete());
}

