    String url = REST_URL + "?" + URLEncodedUtils.format(qparams, "UTF-8");
    URI uri = new URI(url);
    HttpGet httpget = new HttpGet(uri);
    HttpResponse response = httpClient.execute(httpget);
    int status = response.getStatusLine().getStatusCode();
