                    removeDeviceEntry(entry);
                    File src = new File(getConfigPath(), entry.getFileName());
                    File dst = File.createTempFile("dev", ".jar", getConfigPath());
                    IOUtils.copyFile(src, dst);
                    entry.setFileName(dst.getName());
                    addDeviceEntry(entry);
                }
