                createDefaultConfigXml();
            }
            saveConfig();
        }
    } catch (IOException ex) {
        Logger.error(ex);
        createDefaultConfigXml();
    } finally {
        if (configXml == null) {
            createDefaultConfigXml();
        }
    }
    urlsMRU.read(configXml.getChildOrNew("files").getChildOrNew("recent"));
    initSystemProperties();
