public int solution(int X, int [] A) {
    Set<Integer> leaves = new HashSet<>();
    long goal = ((long)X * (X + 1)) / 2;
    long sum = 0;
    for(int i = 0; i < A.length; i++){
        if (A[i] <= X && !leaves.contains(A[i])){
            leaves.add(A[i]);
            sum += A[i];
            if (sum == goal) return i;
        }
    }
    return -1;
}

