        e.printStackTrace();
        try {
            conn.rollback();
        } catch (Exception ep) {
            ep.printStackTrace();
        }
        Pool.close(pm);
        Pool.close(conn);
    } finally {
        Pool.close(pm);
        Pool.close(conn);
    }
    return flag;
}

