public static String getHash(String key) {
    try {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        digest.update(key.getBytes());
        return new BigInteger(digest.digest()).toString(16);
    } catch (NoSuchAlgorithmException e) {
        return key;
    }
}

