public static String encodeByMd5(String str) {
    try {
        if (str == null) {
            str = "";
        }
        MessageDigest md5 = MessageDigest.getInstance("MD5");
        md5.update(str.getBytes("utf-8"));
        byte[] b = md5.digest();
        int i;
        StringBuffer buff = new StringBuffer("");
        for (int offset = 0; offset < b.length; offset++) {
