    System.err.println("Writing IsoFile took  : " + (start3 - start2) + "ms");
    System.err.println("Writing IsoFile speed : " + (new File(String.format("output-%f-%f.mp4", startTime, endTime)).length() / (start3 - start2) / 1000) + "MB/s");
}

