        int sumV = searchedValue * (searchedValue + 1) / 2; 
        int sum = 0; 
        ListIterator < Integer > listIterator = A.listIterator (); 
        while (listIterator.hasNext ()) { 
            int next = listIterator.next (); 
            if (next <= searchedValue) { 
                sum += next; 
            } 
            if (sum == sumV) { 
                return listIterator.previousIndex (); 
            } 
        } 
        return - 1;
}

