public int solution(int X, int[] A) {
    int sumX = ((X+1)*X)/2;
    int sumA = 0;
    Set<Integer> unique = new HashSet<>();
    int i = 0;
    while(i < A.length) {
        if(!unique.contains(A[i])) {
            sumA += A[i];
            unique.add(A[i]);
        }
        if (sumA == sumX) return i;
        i++;
    }
    return -1;
}

