public int solution(int X, int[] A) {
    HashSet<Integer> set = new HashSet<>();
    int sum = 0;
    for (int i = 0; i < A.length; i++) {
        if (A[i] <= X) {
            if(!set.contains(A[i])) {
              set.add(A[i]);
              sum += A[i];
            }
        }
        if(sum == X*(X+1)/2) {
            return i;
        }
    }
    return -1;
}

