public String longestSequenceOfChar (String str) {
    int maxLength = 0;
    String longest = "";
    for(int i = 0, j; i < str.length(); i = j) {
        for(j = i; j < str.length() && str.charAt(j) == str.charAt(i); j++);
        if(j - i > maxLength) {
            maxLength = j - i;
            longest = str.substring(i, j);
        }
    }
    return longest;
}

