public int solution(int X, int[] A) {
    int[] leaves = new int[X + 1];
    int i, distinct = 0;
    for(i = 0; i < A.length; i++) {
        if(leaves[A[i]] == 0) {
            leaves[A[i]] = 1;
            distinct++;
        }
        if(distinct == X) return i;
    }
    return -1;
}

