        FileChannel destinationChannel = new FileOutputStream(out).getChannel();
        try {
            sourceChannel.transferTo(0, sourceChannel.size(), destinationChannel);
        } finally {
            destinationChannel.close();
        }
    } finally {
        sourceChannel.close();
    }
}

