        log.debug("Destination dir: {}", destDir);
        File dir = new File(destDir);
        if (!dir.exists()) {
            if (dir.mkdirs()) {
                log.debug("Directory created");
            } else {
                log.warn("Directory not created");
            }
        }
        dir = null;
    }
    FileOutputStream fo = new FileOutputStream(dest);
    FileChannel foc = fo.getChannel();
    foc.write(mbuf);
    foc.close();
    fo.close();
    fo = null;
    mbuf.clear();
    mbuf = null;
}

