        int n = Integer.parseInt(args[0]);
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        Scanner in = new Scanner(System.in);
        while (in.hasNextInt()) {
            queue.offer(in.nextInt());
        }
        while (queue.size() > n) {
            queue.poll();
        }
