    }
    if (response == 0) {
        saveAs = true;
    }
    if ((saveAs || file == null) && !export) {
        file = ActionUtil.selectFile("Save Map", null);
    } else if (export) {
        file = ActionUtil.selectFile("Export Map", "export");
    }
    if (file == null) {
        try {
