public int solution (final int X, final int [] A){
    int result = -1;
    BitSet filledPosition = new BitSet(X+1);
    for (int i = 0; i < A.length; i++){
        if (A[i] <= X)
            filledPosition.set(A[i]);
        if (filledPosition.cardinality() == X)
            result = i;
    }
    return result;
}

