        resultString = sb.toString();
        bReader.close();
        ((HttpURLConnection) connection).disconnect();
    } catch (java.io.IOException ex) {
        resultString += ex.toString();
    } finally {
        if (bWriter != null) {
            try {
                bWriter.close();
            } catch (Exception ex) {
                resultString += ex.toString();
            }
        }
        if (connection != null) {
            try {
                ((HttpURLConnection) connection).disconnect();
            } catch (Exception ex) {
                resultString += ex.toString();
            }
        }
    }
    return resultString;
}

