public int solution (final int X, final int [] A) {
    boolean[] isLeaf = new boolean[X + 1];
    int unoccupied = X;
    for (int i = 0; i < A.length; i++) {
        if (!isLeaf[A[i]]) {
            isLeaf[A[i]] = true;
            unoccupied--;
            }
        if (unoccupied == 0) {
            return i;
        }
    }
    return -1;
}

