public int solution (int X, int [] A) {
    int len = A.length;
    if (X > len)
        return - 1;
    int [] isFilled = new int [X];
    int jumped = 0;
    java.util.Arrays.fill(isFilled, -1);
    for (int i = 0; i < len; i++) {
        if (A[i] <= X && isFilled [A[i] - 1] == -1) {
            isFilled [A[i] - 1]++;
            jumped ++;
            if (jumped == X) 
                return i;
        }
    }
    return - 1;
}

