        kdc[i][j] = Double.parseDouble(st.nextToken());
        kfc[i][j] = Double.parseDouble(st.nextToken());
        imax = i;
        jmax = j;
        j++;
        k++;
    }
    gridmax = tune_x[i][j - 1];
}

