public int solution(int X, int[] A){
    boolean[] leaves = new boolean[X+1];
    int distinct = 0;
    for(int i=0; i<A.length; i++){
        if(!leaves[A[i]]){
            leaves[A[i]] = true;
            distinct++;
        }
        if(distinct == X){
            return i;
        }
    }
    return -1;
}

