Node reverse(Node head, Node prev) {
    Stack<Node> stack = new Stack<>();
    while (head != null) {
        stack.push(head);
        head = head.next;
    }
    head = stack.pop();
    while (!stack.empty()) {
        head.next = stack.pop();
        head = head.next;
    }
    head.next = null;
    return head;
}

