            stmt = conn.createStatement();
            stmt.executeUpdate(sqlStmts[i]);
            logger.debug(sqlStmts[i]);
            stmt.close();
        }
        conn.commit();
    } catch (SQLException ex) {
        conn.rollback();
        throw ex;
    }
}

