int computeHeight () {
    int maxHeight = 0;
    int [] heights = new int [parent.length];
    for (int vertex = 0;
    vertex < n; vertex ++) {
        if (heights [vertex] != 0) {
            continue;
        }

        int height = 0;
        int i = vertex;
        do {
            if (heights [i] != 0) {
                height += heights [i];
                break;
            }

            height ++;
            i = parent [i];
        } while (i != - 1);

        maxHeight = Math.max (maxHeight, height);
        i = vertex;
        do {
            if (heights [i] != 0) {
                break;
            }

            heights [i] = height --;
            i = parent [i];
        } while (i != - 1);
    }
    return maxHeight;
}

