    int M = P.length;
    int[] result = new int[M];
    int lastA = -1;
    int lastC = -1;
    int lastG = -1;
    for(int i = 0; i < N; i++) {
        char c = S.charAt(i);
        if(c == 'A')
            lastA = i;
        else if(c == 'C')
            lastC = i;
        else if(c == 'G')
            lastG = i;
    }
    for(int i = 0; i < M; i++) {
        int startIndex = P[i];
        int endIndex = Q[i];
        int minimum = 4;

if (startIndex <= lastA && lastA <= endIndex) {
            minimum = 1;
        }
        else if (startIndex <= lastC && lastC <= endIndex) {
            minimum = 2;
        }
        else if (startIndex <= lastG && lastG <= endIndex) {
            minimum = 3;
        }
        result[i] = minimum;
    }
    return result;
}

