public static void copyFileStreams(File fromFile, File toFile) throws IOException {
    if (!fromFile.exists()) {
        return;
    }
    FileInputStream fis = new FileInputStream(fromFile);
    FileOutputStream fos = new FileOutputStream(toFile);
