public static int binarySearch(int[] arr, int first, int last, int value) {
    while (first <= last) {
        int mid = (first + last) / 2;
        if (arr[mid] == value)
            return mid;
        else if (arr[mid] < value)
            first = mid + 1;
        else 
            last = mid - 1;
    }
    return -1;
}

