public static byte [] readBytes (InputStream inputStream) throws IOException {
    byte [] buffer = new byte [32 * 1024];
    int bufferSize = 0;
    for (;;) {
        int read = inputStream.read (buffer, bufferSize, buffer.length - bufferSize);
        if (read == - 1) {
            return Arrays.copyOf (buffer, bufferSize);
        }
        bufferSize += read;
        if (bufferSize == buffer.length) {
            buffer = Arrays.copyOf (buffer, bufferSize * 2);
        }
    }
}

func2:
public static byte [] readBytes (InputStream inputStream) throws IOException {
    int initialBuffSize  = 32 * 1024;
    int maxBufferSize  = 10 * initialBuffSize;
    byte [] buffer = new byte[initialBuffSize];
    int bufferSize = 0;
    while(true) {
        int read = inputStream.read(buffer, 0, initialBuffSize);
        if (read == -1) {
            return Arrays.copyOf(buffer, bufferSize);
        }
        bufferSize += read;
        if (bufferSize == initialBuffSize && bufferSize <= maxBufferSize) {
            buffer = Arrays.copyOf(buffer, bufferSize * 2);
        }
    }
}

