public static int[] removeDuplicates(int[] arr) {
    Set<Integer> repeated = new HashSet<>(arr.length);
    int[] ret = new int[arr.length];
    int c = 0; 
    for (int i = 0; i < arr.length; i++) {
        if(!repeated.contains(arr[i])) {
            repeated.add(arr[i]);
            ret[c++] = arr[i];
        }
    }
    return Arrays.copyOf(ret, c);
}

