public int solution (int X, int[] A) {
    int len = A.length;
    int[] visited = new int[X+1];
    java.util.Arrays.fill(visited, -1);  
    int count = X;
    for (int i = 0; i < len; i++) {
        if (visited[A[i]] == -1) {
            count--;
            visited[A[i]] = 1;
            if (count == 0)
                return i;
        }
    }
    return -1;
}

