public static boolean isPalindrome (String str) {
    str = str.toUpperCase ();
    char [] strChars = str.toCharArray ();
    int wLen = strChars.length;
    while (wLen > 1) {
        if (strChars[0] != strChars[wLen - 1]) {
            return false;
        }
        ++strChars;
        --wLen;
    }
    return true; 
}

