        String result = "";
        int index = 0;
        while(index < text.length()){
            char c = text.charAt(index);
            int count = 0;
            while(c == text.charAt(index)){
                count++;
                index++;
            }
            if(count == 1){
                result += "" + c;
            }
            else{
                result += "" + count + c;
            }
        }
        return result;
}

