public static boolean isPerfectSquare (long n) {
    if (n < 0) {
        return false;
    }
    long guess = 1;
    while (guess * guess < n) {
        guess++;
    }
    if (guess * guess == n) {
        return true;
    } else {
        return false;
    }
}

