        byte[] array = md5.digest();
        StringBuffer sb = new StringBuffer();
        for (int j = 0; j < array.length; ++j) {
            int b = array[j] & 0xFF;
            if (b < 0x10) {
                sb.append('0');
            }
            sb.append(Integer.toHexString(b));
        }
        retValue = sb.toString();
    } catch (UnknownHostException e) {
        System.out.println("Error:" + e);
    }
    return retValue;
}

