    int distinct = -1;
    for (int i = 0; i < A.length; ++i) {
        if (A[i] > X) continue;
        if (aux[A[i]-1] == 0) {
            aux[A[i]-1] = 1;
            distinct++;
        }
        if (distinct == X-1) return i;
    }
    return -1;
}

