    while ((line = br.readLine()) != null && line != "") {
        if (line.startsWith("<tr>") && line.indexOf("[TXT]") >= 0) {
            int i = line.indexOf("href=");
            i = i + 6;
            int j = line.indexOf("\"", i);
            String filename = line.substring(i, j);
            if (filename.matches(".*" + type + ".*")) {
                list.add(filename);
            }
        }
    }
    br.close();
    return list;
}

