static String encrypt(String data) {
    char[] dataChars = data.toCharArray();
    for (int i = 0; i < dataChars.length; i++) {
        if (dataChars[i] >= 'a' && dataChars[i] <= 'y') {
            dataChars[i]++;
        } else if (dataChars[i] == 'z') {
            dataChars[i] = 'a';
        }
    }
    return new String(dataChars);
