public static String encode(String text) {
    try {
        byte[] hash = new byte[32];
        MessageDigest md = MessageDigest.getInstance("MD5");
        md.update(text.getBytes("UTF-8"), 0, text.length());
        hash = md.digest();
        return MD5.toHex(hash);
