boolean isPerfectSquare (long number) {
    if (number < 0) return false;
    if (number == 0 || number == 1) return true;
    for (long i = 2; i <= Math.sqrt(number); i ++) {
        if(number % i == 0) {
            if (number / i == i) return true;
            else return false;
        }
    }
    return false;
}

