            currentSize [0] = bar.getShell ().getSize ().y;
        }
        private boolean compareSizes(){
            return currentSize [0] == orgSize [0];
        }
        private void applyLayoutAndPack(Bar bar){
            bar.getShell ().layout (true);
            bar.getShell ().pack (true);
}

