public int solution(int X, int[] A) {
    int[] count = new int[X+1];
    int sum = 0;
    for (int i = 0; i < A.length; i++) {
        if (count[A[i]] == 0) {
            sum += A[i];
            count[A[i]] = 1;
            if (sum == (X * (X + 1)) / 2) return i;
        }
    }
    return -1;
}

