public void sort (int [] input) {
    for (int i = 0; i < input.length - 1; i++) { 
        for (int k = i + 1; k > 0; k--) { 
            if (input[k - 1] > input[k]) {
                int temp = input[k - 1];
                input[k - 1] = input[k];
                input[k] = temp; 
            }
        }
    }
    System.out.println ("Medium sorting is done and the result is :");
    for (int i : input) {
        System.out.print (i + ",");
    }
}

