        File zipPath = new File(folder);
        File destinationFilePath = new File(zipPath, entry.getName());
        destinationFilePath.getParentFile().mkdirs();
        if (entry.isDirectory()) {
            continue;
        } else {
            out = new FileOutputStream(new File(folder, entry.getName()));
