public static void upload(FTPDetails ftpDetails) {
    FTPClient ftp = new FTPClient();
    try {
        String host = ftpDetails.getHost();
        logger.info("Connecting to ftp host: " + host);
        ftp.connect(host);
        logger.info("Received reply from ftp :" + ftp.getReplyString());
