            log_.info("notifyIhk invoked!");
        } catch (RemoteException ex) {
            System.out.println("----- Could not invoke the method! -----");
            log_.error("Could not invoke the method!");
        }
    } catch (Exception ex) {
        ex.printStackTrace(System.err);
    }
}

