public int maxBlock(String str) { 
    int max = 0, counter = 0;
    for(int i = 1; i < str.length(); i++) {
        if(str.charAt(i) == str.charAt(i-1)) counter++;
        else {
            max = Math.max(max, counter);
            counter = 1;
        }       
    }
    return Math.max(max, counter);
}

